'use strict';
(()=>{
 const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const urls={uk:'https://forum.russia.online/threads/ugolovnyi-kodeks-ro.39487/',upk:'https://forum.russia.online/threads/ugolovno-protsessual-nyi-kodeks-ro.39485/',koap:'https://forum.russia.online/threads/kodeks-ob-administrativnykh-pravonarusheniyakh-ro.39488/'};
 let data={articles:[],documents:[]},ext={index:[],popular:[],quiz:[]},refs={upkIndex:[],admin:[],adminIndex:[],fsb:[],upk:[],labor:[]},catalog=[],cheats=[],general={},fav=read('arb-favorites',[]),history=read('arb-history',[]),topic=read('arb-topic','all'),at=0,score=0,answered=false, rowCache=null, ready=false, quizStarted=false, quickMode='mine';
 const preset=['p317-','p318-1','p318-2','p319-1','p319.1-2','p319.2-1','p105-1','p161-1','p213-1','p139-1','p222-1','p228-1','p228.1-1','p231-1','p314-'];
 let quickList=read('arb-quicklist-v1',null);if(!Array.isArray(quickList))quickList=[...preset];
 function sourceAt(url,number){return number&&url?url.split('#')[0]+'#:~:text='+encodeURIComponent('Статья '+number+'.'):url}
 function jurisdiction(x){return x.jurisdiction?'Подследственность: '+x.jurisdiction:'Подследственность не указана / требует проверки'}
 function addButton(id){let yes=quickList.includes(id);return `<button class="quick-add" data-quick-add="${esc(id)}" aria-pressed="${yes}" aria-label="${yes?'Убрать из моего списка':'Добавить в мой список'}" title="${yes?'Убрать из моего списка':'Добавить в мой список'}">${yes?'✓':'+'}</button>`}
 function read(k,base){try{return JSON.parse(localStorage.getItem(k))??base}catch{return base}}function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Не удалось сохранить настройки')}}function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2500)}
 const topicNames={all:'Все темы',officer:'Сотрудник',detain:'Задержание',person:'Личность',service:'Должностные',justice:'Правосудие',public:'Безопасность',military:'Военная служба',property:'Имущество',drugs:'Наркотики',weapons:'Оружие',territory:'Территории',admin:'КоАП'};
 function group(x){let n=x.number;if(['317','318','319','319.3'].includes(n))return 'officer';if(['319.1','319.2','314'].includes(n))return 'detain';if(['314','314.2'].includes(n))return 'detain';if(['228','228.1','231'].includes(n))return 'drugs';if(['222','222.3','226'].includes(n))return 'weapons';if(['139','213','213.1'].includes(n))return 'territory';let v=parseFloat(n);if(v>=331)return 'military';if(v>=294&&v<=316)return 'justice';if(v>=278&&v<=293)return 'service';if(v>=205&&v<278)return 'public';if(v>=158&&v<205)return 'property';return 'person'}
 function rows(){return rowCache||(rowCache=[...[...ext.popular,...catalog].map(x=>({...x,group:group(x),code:'УК',id:'p'+x.number+'-'+x.part})),...refs.admin.map(x=>({...x,group:'admin',code:'КоАП',id:'adm'+x.number,part:'',stars:null,other:'',admin:true}))])}
 function get(id){let x=rows().find(x=>x.id===id)||data.documents.find(x=>x.id===id)||data.articles.find(x=>x.id===id);if(!x && /^a/.test(id)){let n=id.slice(1);x=rows().find(x=>x.number===n)}return x}
 function favorite(id){fav=fav.includes(id)?fav.filter(x=>x!==id):[...fav,id];save('arb-favorites',fav);renderCurrent()}function remember(id){history=[id,...history.filter(x=>x!==id)].slice(0,10);save('arb-history',history);if(currentView()==='saved')renderSaved()}
 function action(id){return `<button class="star-btn" data-fav="${esc(id)}" aria-pressed="${fav.includes(id)}" aria-label="${fav.includes(id)?'Убрать из избранного':'В избранное'}">${fav.includes(id)?'★':'☆'}</button>`}
 function table(data,target){$(target).innerHTML=data.map(x=>{let star=x.admin||x.stars===null?'—':x.stars===0?(x.starsText||'★–★★★★★'):'★'.repeat(x.stars);let term=x.admin?`Штраф ${x.term}`:`${x.term}${x.number==='314'||x.formula||x.fineOnly?'':' лишения свободы'}`;return `<article class="table-row"><div class="row-code"><span>${esc(x.code)} · ${esc(x.number)}</span>${x.part?`<small>часть ${esc(x.part)}</small>`:''}<small>${esc(jurisdiction(x))}</small></div><div class="row-title">${esc(x.title)}</div><div class="row-stars" aria-label="${x.admin?'КоАП, без звёзд':esc(star)}">${esc(star)}</div><div class="row-penalty">${esc(term)}${x.other?`<small>${esc(x.other)}</small>`:''}</div><div class="row-actions">${action(x.id)}${addButton(x.id)}<a href="${esc(sourceAt(x.url,x.number))}" data-open="${esc(x.id)}" target="_blank" rel="noopener" aria-label="Открыть источник">↗</a></div></article>`}).join('')||'<p class="empty">Ничего не найдено. Попробуйте другой запрос.</p>'}
 function renderTables(){let all=rows();if(currentView()==='popular'){let q=$('#popular-search').value.toLocaleLowerCase('ru').trim();table(all.filter(x=>!x.catalog).filter(x=>[x.number,x.title,x.part,x.code,x.jurisdiction].join(' ').toLocaleLowerCase('ru').includes(q)),'#popular-list');return}if(currentView()!=='quick')return;let query=$('#quick-search').value.toLocaleLowerCase('ru').trim();let selected=quickMode==='mine'?quickList:quickMode==='preset'?preset:null;let base=selected?selected.map(id=>all.find(x=>x.id===id)).filter(Boolean):all;let filtered=base.filter(x=>(topic==='all'||x.group===topic)&&[x.number,x.part,x.title,x.other,x.code,x.term,x.jurisdiction].join(' ').toLocaleLowerCase('ru').includes(query));table(filtered,'#quick-list');if(!filtered.length&&quickMode==='mine'&&!query&&topic==='all')$('#quick-list').innerHTML='<p class="empty">Список пуст. Откройте «Все статьи» и добавьте нужные кнопкой +.</p>';$('#quick-title').textContent=(quickMode==='mine'?'Мой список':quickMode==='preset'?'Популярный набор':'Все статьи')+' · '+(topicNames[topic]||topicNames.all);$('#quick-count').textContent=`${filtered.length} записей · сверка 28.10.2026`;document.querySelectorAll('[data-quick-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.quickMode===quickMode)));$('#topics').innerHTML=Object.entries(topicNames).map(([id,name])=>`<button class="topic-node ${topic===id?'active':''}" data-topic="${id}" aria-pressed="${topic===id}"><i></i><span>${name}</span><small>${id==='all'?base.length:base.filter(x=>x.group===id).length}</small></button>`).join('')}

 function renderDocs(){let f=$('#doc-filter').value;$('#documents-list').innerHTML=data.documents.filter(d=>f==='all'||d.category===f).map(d=>`<article class="doc-row"><span class="tag">${esc(d.category)}</span><div><h3>${esc(d.title)}</h3><p>${esc(d.summary)}</p><small>${esc(d.status)} · каталог проверен ${esc(d.checked)}</small></div><div class="doc-actions">${action(d.id)}<a href="${esc(d.url)}" data-open="${esc(d.id)}" target="_blank" rel="noopener">Форум ↗</a></div></article>`).join('')}
 function index(list,query,target,source){let q=$(query).value.trim().toLocaleLowerCase('ru'),out=list.filter(x=>(x.number+' '+x.title).toLocaleLowerCase('ru').includes(q));let isUk=target==='#uk-list',isAdmin=target==='#admin-index';$(target).innerHTML=out.map(x=>{let parts=isUk?rows().filter(z=>z.code==='УК'&&z.number===x.number):isAdmin?rows().filter(z=>z.admin&&z.number===x.number):[];let summary=isUk?general[x.number]:isAdmin?'':(refs.upk.find(z=>new RegExp('(?:^|\\D)'+x.number.replace('.','\\.')+'(?:\\D|$)').test(z.source))||{}).text;let scope=parts.length?[...new Set(parts.map(z=>z.jurisdiction||'требует проверки'))].join(' / '):'не указана / требует проверки';return `<details class="index-entry" data-entry="${esc(x.number)}"><summary><b>${esc(x.number)}</b><span>${esc(x.title)}<br><small class="jurisdiction-note">${isUk?'Подследственность: '+esc(scope):'Подследственность: не указана / требует проверки'}</small></span><span>＋</span></summary><div class="index-detail">${summary?'<p>'+esc(summary)+'</p>':''}${parts.length?parts.map(z=>{let star=z.admin?'без звёзд':z.stars===null?'без звёзд':z.stars===0?(z.starsText||'★–★★★★★'):'★'.repeat(z.stars);return `<p><b>${z.part?'Часть '+esc(z.part):'Статья целиком'}</b> · ${esc(z.title)}<br><span class="row-stars">${esc(star)}</span> · ${esc(z.term)} · ${esc(jurisdiction(z))}${z.other?'<br>'+esc(z.other):''}</p><div class="inline-actions">${action(z.id)}${addButton(z.id)}</div>`}).join(''):(summary?'':'<p>Подробное содержание пока не добавлено. Требуется сверка первоисточника.</p>')}<a href="${esc(sourceAt(source,x.number))}" target="_blank" rel="noopener">Перейти к статье в источнике ↗</a></div></details>`}).join('')||'<p class="empty">Ничего не найдено.</p>';if(isUk)$('#uk-count').textContent=`${out.length} из ${list.length} статей`;if(isAdmin)$('#admin-count').textContent=`${out.length} из ${list.length} пунктов`}

 function renderCheats(){$('#cheat-list').innerHTML=cheats.map(x=>`<article class="panel cheat-card"><div class="cheat-top"><span>${esc(x.number)} / ПАМЯТКА</span><span>↗</span></div><h2>${esc(x.title)}</h2><p>${esc(x.subtitle)}</p><ol>${x.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><a href="${esc(sourceAt(x.url,(x.source.match(/(?:ст\.?|стать[ияе])\s*(\d+(?:\.\d+)?)/i)||[])[1]))}" target="_blank" rel="noopener">${esc(x.source)} ↗</a></article>`).join('')}
 function renderRef(list,target){$(target).innerHTML=list.map(x=>`<article class="panel"><p class="eyebrow">${esc(x.source)}</p><h2>${esc(x.title)}</h2><p>${esc(x.text)}</p><a href="${esc(sourceAt(x.url,(x.source.match(/(?:ст\.?|стать[ияе])\s*(\d+(?:\.\d+)?)/i)||[])[1]))}" target="_blank" rel="noopener">Первоисточник ↗</a></article>`).join('')}
 function renderAdmin(){table(refs.admin.map(x=>({...x,code:'КоАП',id:'adm'+x.number,admin:true})),'#admin-list')}
 function renderSaved(){ $('#fav-count').textContent=fav.length;for(const [el,items,msg] of [['#favorites',fav,'Пока нет избранных материалов.'],['#history',history,'История пока пуста.']])$(el).innerHTML=items.map(id=>{let x=get(id);return x?`<div class="saved-item"><a href="${esc(x.number?sourceAt(x.url,x.number):x.url)}" data-open="${esc(id)}" target="_blank" rel="noopener">${esc(x.code?x.code+' '+x.number+' '+x.title:x.title)} ↗</a>${el==='#favorites'?action(id):''}</div>`:''}).join('')||`<p class="empty">${msg}</p>`}
 function renderSearch(){if(!ready){$('#search-results').innerHTML='<p class="empty">Загружаем данные…</p>';return}let q=$('#global-search').value.toLocaleLowerCase('ru').trim();if(!q){$('#search-results').innerHTML='';return}let all=[...ext.index.map(x=>({title:x.title,number:x.number,code:'УК',summary:general[x.number]||'',url:'#uk/'+x.number})),...refs.upkIndex.map(x=>({title:x.title,number:x.number,code:'УПК',url:'#upk/'+x.number})),...refs.adminIndex.map(x=>({...x,code:'КоАП',url:'#koap/'+x.number})),...cheats.map(x=>({title:x.title,summary:x.steps.join(' '),code:'Шпаргалка',url:x.url})),...data.documents.map(x=>({...x,code:x.category}))].filter(x=>[x.title,x.number,x.code,x.summary].filter(Boolean).join(' ').toLocaleLowerCase('ru').includes(q));$('#search-results').innerHTML=all.slice(0,12).map(x=>`<a href="${esc(x.url)}" ${x.url.startsWith('#')?'':'target="_blank" rel="noopener"'}><span>${esc(x.code)} ${esc(x.number||'')}</span><strong>${esc(x.title)}</strong><b>↗</b></a>`).join('')||'<p class="empty">Ничего не найдено в загруженных материалах.</p>'}
 function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}function quiz(){answered=false;let q=ext.quiz[at];$('#quiz-feedback').innerHTML='';$('#quiz-next').disabled=true;$('#quiz-next').textContent='Следующий вопрос →';$('#quiz-score').textContent='Верно: '+score;$('#quiz-progress').textContent=`Ситуация ${at+1} / ${ext.quiz.length}`;$('#quiz-bar').style.width=`${at/ext.quiz.length*100}%`;$('#quiz-question').textContent=q.question;$('#quiz-options').innerHTML=shuffle(q.options.map((value,index)=>({value,index}))).map(x=>`<button data-option="${x.index}">${esc(x.value)}</button>`).join('')}
 function route(){let raw=decodeURIComponent(location.hash.slice(1))||'home', [hash,entry]=raw.split('/');let aliases={'uk-index':'uk','articles':'popular','start':'home'};if(hash.startsWith('doc-'))hash='documents';if(hash.startsWith('article-'))hash='popular';hash=aliases[hash]||hash;let active=document.querySelector(`[data-view="${CSS.escape(hash)}"]`);if(!active){hash='home';active=$('[data-view="home"]')}document.querySelectorAll('.view').forEach(v=>v.hidden=v!==active);document.querySelectorAll('#nav a').forEach(a=>{let on=a.getAttribute('href')==='#'+hash;on?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});document.body.classList.toggle('is-quick',hash==='quick');$('#nav').classList.remove('open');$('#menu-btn').setAttribute('aria-expanded','false');window.scrollTo(0,0);if(ready){renderCurrent();if(entry){let item=active.querySelector('[data-entry="'+CSS.escape(entry)+'"]');if(item){item.open=true;requestAnimationFrame(()=>item.scrollIntoView({block:'center'}))}}}$('#loading').hidden=ready||hash==='home';document.title=(hash==='home'?'Арбатский':(topicNames[hash]||active.querySelector('h1')?.textContent||'Арбатский'))+' · Правовой портал'}
 function currentView(){return document.querySelector('.view:not([hidden])')?.dataset.view||'home'}
 function renderCurrent(){if(!ready)return;$('#fav-count').textContent=fav.length;switch(currentView()){case 'home':renderSearch();break;case 'documents':renderDocs();break;case 'quick':case 'popular':renderTables();break;case 'uk':index(ext.index,'#uk-search','#uk-list',urls.uk);break;case 'upk':renderRef(refs.upk,'#upk-highlights');index(refs.upkIndex,'#upk-search','#upk-list',urls.upk);break;case 'fsb':renderRef(refs.fsb,'#fsb-content');break;case 'labor':renderRef(refs.labor,'#labor-content');break;case 'koap':renderAdmin();index(refs.adminIndex,'#admin-search','#admin-index',urls.koap);break;case 'cheats':renderCheats();break;case 'saved':renderSaved();break;case 'study':if(!quizStarted){quizStarted=true;quiz()}break}}
 function init(){if(!topicNames[topic])topic='all';ready=true;$('#loading').hidden=true;route()}

 window.addEventListener('hashchange',route);$('#menu-btn').onclick=()=>{let open=$('#nav').classList.toggle('open');$('#menu-btn').setAttribute('aria-expanded',String(open))};$('#doc-filter').onchange=renderDocs;$('#popular-search').oninput=renderTables;$('#quick-search').oninput=renderTables;$('#uk-search').oninput=()=>index(ext.index,'#uk-search','#uk-list',urls.uk);$('#upk-search').oninput=()=>index(refs.upkIndex,'#upk-search','#upk-list',urls.upk);$('#admin-search').oninput=()=>index(refs.adminIndex,'#admin-search','#admin-index',urls.koap);$('#global-search').oninput=renderSearch;$('#clear-search').onclick=()=>{$('#global-search').value='';renderSearch();$('#global-search').focus()};$('#clear-history').onclick=()=>{history=[];save('arb-history',history);if(currentView()==='saved')renderSaved()};
 document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return}let mode=e.target.closest('[data-quick-mode]');if(mode){quickMode=mode.dataset.quickMode;topic='all';save('arb-topic',topic);renderTables()}let add=e.target.closest('[data-quick-add]');if(add){let id=add.dataset.quickAdd;quickList=quickList.includes(id)?quickList.filter(x=>x!==id):[...quickList,id];save('arb-quicklist-v1',quickList);let openEntry=add.closest('details')?.dataset.entry;renderCurrent();if(openEntry){let detail=document.querySelector('[data-view="'+currentView()+'"] [data-entry="'+CSS.escape(openEntry)+'"]');if(detail)detail.open=true}toast(quickList.includes(id)?'Добавлено в мой список':'Убрано из моего списка')}let t=e.target.closest('[data-topic]');if(t){topic=t.dataset.topic;save('arb-topic',topic);renderTables()}let f=e.target.closest('[data-fav]');if(f)favorite(f.dataset.fav);let a=e.target.closest('[data-open]');if(a)remember(a.dataset.open)});
 $('#copy-miranda').onclick=async()=>{let text=$('#miranda-text').textContent;try{await navigator.clipboard.writeText(text);toast('Текст скопирован')}catch{let t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();try{document.execCommand('copy')?toast('Текст скопирован'):toast('Не удалось скопировать')}catch{toast('Не удалось скопировать')}t.remove()}};
 $('#quick-reset').onclick=()=>{quickList=[...preset];save('arb-quicklist-v1',quickList);quickMode='mine';topic='all';save('arb-topic',topic);renderTables();toast('Популярный шаблон восстановлен')};
 $('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('Полный экран недоступен. Попробуйте F11 в браузере.')}};document.addEventListener('fullscreenchange',()=>$('#fullscreen').textContent=document.fullscreenElement?'Выйти из полного экрана ⛶':'На весь экран ⛶');
 $('#quiz-options').onclick=e=>{let b=e.target.closest('[data-option]');if(!b||answered)return;answered=true;let q=ext.quiz[at],good=Number(b.dataset.option)===q.correct;if(good)score++;for(let el of $('#quiz-options').querySelectorAll('button')){el.disabled=true;if(Number(el.dataset.option)===q.correct)el.classList.add('correct');else if(el===b)el.classList.add('incorrect')}$('#quiz-score').textContent='Верно: '+score;$('#quiz-feedback').innerHTML=`<strong>${good?'Верно':'Не совсем'}</strong><p>${esc(q.explanation)}</p><a href="${esc(sourceAt(q.url,(q.source.match(/(?:ст\.?|стать[ияе])\s*(\d+(?:\.\d+)?)/i)||[])[1]))}" target="_blank" rel="noopener">${esc(q.source)} ↗</a>`;$('#quiz-next').disabled=false;$('#quiz-next').textContent=at===ext.quiz.length-1?'Показать результат →':'Следующий вопрос →'};$('#quiz-next').onclick=()=>{if(!answered)return;at++;if(at===ext.quiz.length){$('#quiz-progress').textContent='Тест завершён';$('#quiz-bar').style.width='100%';$('#quiz-question').textContent=`Результат: ${score} / ${ext.quiz.length}`;$('#quiz-options').innerHTML='';$('#quiz-feedback').innerHTML='<p>Повторите сложные ситуации и сверьтесь с первоисточником.</p>';$('#quiz-next').disabled=true}else quiz()};$('#quiz-restart').onclick=()=>{at=0;score=0;quiz()};
 route();
 Promise.all(['data.json','extended.json','references.json','catalog.json','cheats.json','general.json'].map(p=>fetch('./'+p+'?v=12').then(r=>{if(!r.ok)throw Error(p);return r.json()}))).then(([d,x,r,c,h,g])=>{data=d;ext=x;refs=r;catalog=c;cheats=h;general=g;init()}).catch(()=>{$('#loading').textContent='Не удалось загрузить данные. Проверьте файлы справочника и подключение.'});
})();
